pet_cycleind_symm :=
proc(n)
option remember;
local l;

    if n=0 then return 1; fi;

    expand(1/n*add(a[l]*pet_cycleind_symm(n-l), l=1..n));
end;

pet_autom2cycles :=
proc(src, aut)
local numa, numsubs, k;
local marks, pos, cycs, cpos, clen;

    numsubs := [seq(src[k]=k, k=1..nops(src))];
    numa := subs(numsubs, aut);

    marks := Array([seq(true, pos=1..nops(aut))]);

    cycs := []; pos := 1;

    while pos <= nops(aut) do
        if marks[pos] then
            clen := 0; cpos := pos;

            while marks[cpos] do
                marks[cpos] := false;
                cpos := numa[cpos];
                clen := clen+1;
            od;

            cycs := [op(cycs), clen];
        fi;

        pos := pos+1;
    od;

    return mul(a[cycs[k]], k=1..nops(cycs));
end;


pet_prod2rep :=
proc(varp)
    local v, d, q, res, len, cyc, p;

    q := 1; res := [];

    for v in indets(varp) do
        d := degree(varp, v);
        len := op(1, v);

        for cyc to d do
            res :=
            [op(res),
             seq(p, p=q+1..q+len-1), q];
            q := q+len;
        od;
    od;

    res;
end;



pet_cycleind_HCE :=
proc(n)
option remember;
local idx, vert, verts, edges, bits, u, v, pos, q,
    symind, cind, term, rep, flip, edge, subl, autom;

    verts := [];
    edges := [];

    for idx from 2^n to 2*2^n-1 do
        bits := convert(idx, `base`, 2)[1..n];

        verts :=  [op(verts), bits];

        for pos to n do
            if bits[pos] = 0 then
                u := bits;
                v := [seq(bits[q], q=1..pos-1),
                      1, seq(bits[q], q=pos+1..n)];

                edges :=  [op(edges), {u,v}];
            fi;
        od;
    od;

    if n=1 then
        symind := [a[1]];
    else
        symind := pet_cycleind_symm(n);
    fi;


    cind := 0;

    for term in symind do
        rep := pet_prod2rep(term);
        for flip in verts do
            subl := [];

            for vert in verts do
                subl :=
                [op(subl),
                 vert =
                 [seq(`if`(flip[q]=1,
                       1-vert[rep[q]],
                       vert[rep[q]]),
                      q=1..n)]];
            od;

            autom := subs(subl, edges);
            cind := cind + lcoeff(term)*
            pet_autom2cycles(edges, autom);
        od;
    od;

    cind/2^n;
end;

HCE_colorings :=
proc(n, N)
option remember;
local cind, vars, v;

    cind := pet_cycleind_HCE(n);
    vars := indets(cind);

    subs([seq(v=N, v in vars)], cind);
end;


